import type {
  Channel,
  NoticePriority,
  TemplateApproval,
  TemplateCategory,
} from '@/features/communication/types';

/**
 * Communication seed for the development mock.
 *
 * Templates and notices. Messages are generated by `devApi` so their audiences
 * resolve against the live rosters — a sent message hard-coded to "412
 * recipients" would drift from the student list the moment anybody was
 * admitted, and the whole point of an audience being a query is that it does
 * not.
 *
 * Deliberately mixed: one template per channel, a WhatsApp one still awaiting
 * Meta's approval and another rejected, a retired one, and an SMS body with a
 * curly quote in it so the unicode warning is reachable without typing one.
 */

export interface TemplateSeed {
  id: number;
  name: string;
  code: string;
  channel: Channel;
  category: TemplateCategory;
  subject?: string;
  body: string;
  approval?: TemplateApproval;
  approvalNote?: string;
  isActive?: boolean;
}

