export interface NoticeSeed {
  id: number;
  title: string;
  body: string;
  category: TemplateCategory;
  priority: NoticePriority;
  audienceType: 'all_students' | 'all_guardians' | 'all_teachers' | 'all_staff' | 'class';
  status: 'draft' | 'pending_approval' | 'published' | 'expired' | 'archived';
  /** Days from today. Negative is in the past. */
  publishIn: number;
  expiresIn: number | null;
  isPinned?: boolean;
  announcements?: number;
}

